package com.crm.customer.controller;
import com.crm.customer.entity.Customer; import com.crm.customer.repository.CustomerRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/customers") public class CustomerController { private final CustomerRepository repo; public CustomerController(CustomerRepository repo){this.repo=repo;} @GetMapping public List<Customer> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Customer> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Customer> create(@RequestBody Customer x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} @PutMapping("/{id}") public ResponseEntity<Customer> update(@PathVariable Long id,@RequestBody Customer x){return repo.findById(id).map(e->{e.setName(x.getName());e.setEmail(x.getEmail());e.setPhone(x.getPhone());e.setAddress(x.getAddress());e.setStatus(x.getStatus());return ResponseEntity.ok(repo.save(e));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }